from collections import Counter
from typing import List

def countPairs(a: List[int]) -> int:
    def digit_sum(x: int) -> int:
        s = 0
        while x:
            s += x % 10
            x //= 10
        return s
    cnt = Counter(digit_sum(x) for x in a)
    return sum(c * (c - 1) // 2 for c in cnt.values())
